using AIPMS.Application.Abstractions.Security;using AIPMS.Application.Common.Exceptions;using AIPMS.Application.Features.Evaluations.Abstractions;using AIPMS.Application.Features.Evaluations.DTOs;using MediatR;
namespace AIPMS.Application.Features.Evaluations.Commands;
public sealed record CreateEvaluationDraftCommand(long ProjectId,string EvaluationType):IRequest<EvaluationDetailDto>;public sealed record UpdateEvaluationScoreCommand(long EvaluationId,long CriterionId,decimal Score,string? Comments):IRequest<Unit>;public sealed record UpdateEvaluationCommentCommand(long EvaluationId,string? Comments):IRequest<Unit>;public sealed record FinalizeEvaluationCommand(long EvaluationId):IRequest<Unit>;
public static class EvaluationAccess { public static long UserId(ICurrentUser u)=>u.UserId??throw new ForbiddenException(); public static async Task Ensure(long uid,EvaluationDetailDto e,IEvaluationRepository r,CancellationToken ct){if(e.Evaluation.EvaluatorId!=uid&&!await r.CanEvaluateProjectAsync(uid,e.Evaluation.ProjectId,ct))throw new ForbiddenException();}}
public sealed class CreateEvaluationDraftHandler(ICurrentUser u,IEvaluationRepository r):IRequestHandler<CreateEvaluationDraftCommand,EvaluationDetailDto>{public async Task<EvaluationDetailDto> Handle(CreateEvaluationDraftCommand x,CancellationToken ct){var uid=EvaluationAccess.UserId(u);var type=x.EvaluationType.Trim().ToUpperInvariant();if(!new[]{"SUPERVISOR","LECTURER","COMMITTEE","FINAL"}.Contains(type))throw new ValidationException(new Dictionary<string,string[]>{{"evaluationType",["Unsupported evaluation type."]}});if(!await r.ProjectExistsAsync(x.ProjectId,ct))throw new NotFoundException("Project",x.ProjectId);if(!await r.CanEvaluateProjectAsync(uid,x.ProjectId,ct))throw new ForbiddenException();var id=await r.CreateDraftAsync(x.ProjectId,uid,type,ct);return await r.GetAsync(id,ct)??throw new NotFoundException("Evaluation",id);}}
public sealed class UpdateEvaluationScoreHandler(ICurrentUser u,IEvaluationRepository r):IRequestHandler<UpdateEvaluationScoreCommand,Unit>{public async Task<Unit> Handle(UpdateEvaluationScoreCommand x,CancellationToken ct){var e=await r.GetAsync(x.EvaluationId,ct)??throw new NotFoundException("Evaluation",x.EvaluationId);await EvaluationAccess.Ensure(EvaluationAccess.UserId(u),e,r,ct);if(e.Evaluation.Status!="DRAFT")throw new ConflictException("Only draft evaluations can be changed.");var c=e.Scores.SingleOrDefault(s=>s.CriterionId==x.CriterionId)??throw new NotFoundException("EvaluationCriterion",x.CriterionId);if(x.Score<0||x.Score>c.MaxScore)throw new ValidationException(new Dictionary<string,string[]>{{"score",[$"Score must be between 0 and {c.MaxScore}."]}});await r.UpsertScoreAsync(x.EvaluationId,x.CriterionId,x.Score,x.Comments,ct);return Unit.Value;}}
public sealed class UpdateEvaluationCommentHandler(ICurrentUser u,IEvaluationRepository r):IRequestHandler<UpdateEvaluationCommentCommand,Unit>{public async Task<Unit> Handle(UpdateEvaluationCommentCommand x,CancellationToken ct){var e=await r.GetAsync(x.EvaluationId,ct)??throw new NotFoundException("Evaluation",x.EvaluationId);await EvaluationAccess.Ensure(EvaluationAccess.UserId(u),e,r,ct);if(e.Evaluation.Status!="DRAFT")throw new ConflictException("Only draft evaluations can be changed.");await r.UpdateCommentsAsync(x.EvaluationId,x.Comments,ct);return Unit.Value;}}
public sealed class FinalizeEvaluationHandler(ICurrentUser u,IEvaluationRepository r,IEvaluationScoreCalculator calc,TimeProvider clock):IRequestHandler<FinalizeEvaluationCommand,Unit>{public async Task<Unit> Handle(FinalizeEvaluationCommand x,CancellationToken ct){var e=await r.GetAsync(x.EvaluationId,ct)??throw new NotFoundException("Evaluation",x.EvaluationId);await EvaluationAccess.Ensure(EvaluationAccess.UserId(u),e,r,ct);if(e.Evaluation.Status!="DRAFT")throw new ConflictException("Evaluation is already submitted or finalized.");if(e.Scores.Count==0||e.Scores.Any(s=>s.Score is null))throw new ConflictException("All active criteria must have scores.");var total=calc.Calculate(e.Scores.Select(s=>new ScoreInput(s.Score!.Value,s.MaxScore,s.WeightPercent)));if(!await r.FinalizeAsync(x.EvaluationId,total,clock.GetUtcNow().UtcDateTime,ct))throw new ConflictException("Evaluation was finalized concurrently.");return Unit.Value;}}
